const ANYBIKE_LOGO_PNG_BASE64 = "";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.57.0";
Deno.serve(async (req:Request)=>{
 if(req.method!=="POST")return new Response("Method not allowed",{status:405});
 const key=Deno.env.get("SUPABASE_SERVICE_ROLE_KEY"),url=Deno.env.get("SUPABASE_URL");
 if(!key||!url||req.headers.get("Authorization")!=="Bearer "+key)return new Response("Forbidden",{status:403});
 const db=createClient(url,key,{auth:{persistSession:false}});
 const {data:claim,error}=await db.rpc("anybike_claim_onboarding_email");
 if(error)return Response.json({error:error.message},{status:500});
 if(claim?.action!=="claimed")return Response.json({result:claim});
 const id=claim.outbox_id;
 const link="https://www.anybike.co.uk/customer-messages.html?thread="+encodeURIComponent(String(claim.thread_id));
 const apiKey=Deno.env.get("RESEND_API_KEY");
 if(!apiKey){await db.from("anybike_onboarding_email_outbox").update({status:"failed",last_error:"Email provider not configured"}).eq("id",id);return Response.json({error:"Email provider not configured"},{status:503});}
 try{
  const reply=await fetch("https://api.resend.com/emails",{method:"POST",headers:{"Authorization":"Bearer "+apiKey,"Content-Type":"application/json","Idempotency-Key":"anybike-onboarding-"+id},body:JSON.stringify({from:"AnyBike <no-reply@anybike.co.uk>",to:[claim.email],subject:"New AnyBike message",html:'<!doctype html><html><body style="margin:0;padding:0;background:#f2f2f2;font-family:Arial,Helvetica,sans-serif;color:#161616"><table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="background:#f2f2f2"><tr><td align="center" style="padding:28px 12px"><table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="max-width:620px;background:#fff;border:1px solid #dedede"><tr><td align="center" style="background:#ffffff;padding:22px 25px;border-bottom:4px solid #ed1c24"><img src="cid:anybike-email-logo" alt="AnyBike" width="225" style="display:block;max-width:100%;height:auto;border:0"></td></tr><tr><td style="padding:30px 32px"><p style="color:#bd101a;font-size:12px;font-weight:bold;letter-spacing:1px">ANYBIKE MESSAGE CENTRE</p><h1 style="font-size:25px;line-height:1.3;margin:12px 0 20px">You have a new message from AnyBike</h1><p style="font-size:16px;line-height:1.6">A new message is ready in your AnyBike account. Open your conversation to read and reply securely.</p><p style="margin:28px 0"><a href="'+link+'" style="display:inline-block;background:#ed1c24;padding:14px 24px;border-radius:6px;color:#fff;text-decoration:none;font-weight:bold">View your message</a></p><p style="font-size:13px;color:#666">For security, please reply through the AnyBike Message Centre rather than this email.</p></td></tr><tr><td style="background:#111;color:#ddd;padding:18px 32px;font-size:12px;line-height:1.6">AnyBike.co.uk | Motorcycle trading and export<br>This is an automated email from AnyBike.</td></tr></table></td></tr></table></body></html>',attachments:[{filename:"anybike-email-logo.png",content:ANYBIKE_LOGO_PNG_BASE64,content_type:"image/png",content_id:"anybike-email-logo"}]})});
  const result=await reply.json().catch(()=>({}));
  const status=reply.ok?"submitted":reply.status>=500||reply.status===429?"unknown":"failed";
  await db.from("anybike_onboarding_email_outbox").update({status,provider_email_id:result.id||null,submitted_at:reply.ok?new Date().toISOString():null,last_error:reply.ok?null:"Provider status "+reply.status}).eq("id",id).eq("status","sending");
  return Response.json({outbox_id:id,status});
 }catch(e){
  await db.from("anybike_onboarding_email_outbox").update({status:"unknown",last_error:String(e).slice(0,250)}).eq("id",id).eq("status","sending");
  return Response.json({outbox_id:id,status:"unknown",review_required:true});
 }
});